{
  "status": "SUPPORTED",
  "task_summary": "Distribute refreshment settings to two seating positions and place a remote control in a central accessible location.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "Set of drinkware and dish for one person",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cup", "plate", "napkin"],
        "required_properties": [
          "holds_refreshment_content",
          "fits_in_hand"
        ]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Device for operating media equipment",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["remote", "controller", "mobile_device"],
        "required_properties": [
          "operates_tv_or_audio"
        ]
      },
      {
        "id": "viewing_seat",
        "entity_kind": "FIXED_TARGET",
        "function": "Stationary seating location for a viewer",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["armchair", "sofa", "bench"],
        "required_properties": [
          "supports_sitting",
          "has_leg_space"
        ]
      },
      {
        "id": "surface_platform",
        "entity_kind": "REGION",
        "function": "Flat planar area for supporting objects",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": ["coffee table", "side table", "desk"],
        "required_properties": [
          "is_horizontal",
          "is_sturdy_enough_for_items"
        ]
      }
    ],
    "functional_relations": [
