        "relation": "assigned_to_person_seating_area",
        "object_role": "viewing_seat",
        "required": true
      },
      {
        "id": "rel_002",
        "subject_role": "refreshment_setting",
        "relation": "located_at_proximity_of",
        "object_role": "viewing_seat",
        "required": true
      },
      {
        "id": "rel_003",
        "subject_role": "entertainment_control",
        "relation": "accessible_by_all_viewers",
        "object_role": "viewing_seat",
        "required": true
      },
      {
        "id": "rel_004",
        "subject_role": "refreshment_setting",
        "relation": "supported_by",
        "object_role": "surface_platform",
        "required": true
      },
      {
        "id": "rel_005",
        "subject_role": "entertainment_control",
        "relation": "supported_by",
        "object_role": "surface_platform",
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "op_001",
        "operation": "place_refreshment_setting_on_nearby_surface",
        "source_role": "refreshment_setting",
        "target_role": "surface_platform",
        "operation_count": 2,
        "reuse_policy": "DEDICATED_PER_TARGET",
        "anchor_role": "viewing_seat"
      },
      {
        "id": "op_002",
        "operation": "place_entertainment_control_in_central_access_spot",
        "source_role": "entertainment_control",
        "target_role": "surface_platform",
        "operation_count": 1,
        "reuse_policy": "DEDICATED_PER_TARGET",
        "anchor_role": "viewing_seat"
      }
    ]
  },
